INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l45','make a poor show of','',NULL,'/meɪk ə pʊr ʃoʊ ʌv/','I would make a poor show of disputing a cave with a bear.','我去和熊争山洞会表现得很糟。','He made a poor show of hiding his fear.','他掩饰恐惧的样子很拙劣。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l45','look on','',NULL,'/lʊk ɑːn/','Someone looking on from outside can inject a new thought.','从外面旁观的人能注入新念头。','The crowd looked on in silence.','人群默默地旁观着。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l45','turn upside down','',NULL,'/tɜːrn ˈʌpsaɪd daʊn/','A few pages of ideas could turn the world upside down.','几页观念就能把世界搅个天翻地覆。','The news turned his life upside down.','那消息把他的生活彻底搅乱了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l45','no longer','',NULL,'/noʊ ˈlɔːŋɡər/','The environment is no longer essentially physical.','环境已不再本质上是物质性的。','He no longer works here.','他不再在这里工作了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp1','choice','{"stem":"\"Their development differs not so much because of resources ___ because of belief.\"(‘与其说…不如说…’= not so much A __ B,填连接 B 的那个词)","options":["but","than","so","as"],"answer_index":3,"stem_cn":"它们的差异,与其说源于资源,不如说源于信念。","explanation_cn":"not so much A as B,‘与其说A不如说B’;连接 B 用 as。✓ not so much resources as belief. ✗ than / but / so:此结构用 as。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp1','choice','{"stem":"\"The danger lies not so much in weapons ___ in ideas.\"(‘与其说A不如说B’,填连接 B 的那个词)","options":["or","than","as","but"],"answer_index":2,"stem_cn":"危险与其说在于武器,不如说在于观念。","explanation_cn":"not so much A as B;连接 B 用 as。✓ not so much in weapons as in ideas. ✗ than / but / or:此结构用 as。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp1','choice','{"stem":"\"Man''s struggle is now not so ___ against nature as against himself.\"(‘与其说…不如说…’结构,填 not so 与 as 之间的那个词)","options":["far","long","many","much"],"answer_index":3,"stem_cn":"人如今的斗争,与其说是对抗自然,不如说是对抗自己。","explanation_cn":"not so much … as …;not so 与 as 之间填 much。✓ not so much against nature as against himself. ✗ many / far / long:此结构用 much。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp2','choice','{"stem":"\"A few pages of information ___ have been enough to change history in 1925.\"(与过去事实相反的虚拟,主句是‘情态动词 + have + 过去分词’,填那个情态动词)","options":["will","shall","would","do"],"answer_index":2,"stem_cn":"1925年,几页资料本足以改变历史。","explanation_cn":"与过去事实相反的虚拟,主句用 would + have + 过去分词;填情态动词 would。✓ would have been enough. ✗ will(不用于虚拟)/ shall / do:虚拟主句用 would。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp2','choice','{"stem":"\"If they had known the secret, they ___ have built the device.\"(if 从句用过去完成,主句用‘情态动词 + have + 过去分词’,填那个情态动词)","options":["can","must","will","would"],"answer_index":3,"stem_cn":"倘若他们知道那个秘密,本会造出那装置。","explanation_cn":"与过去相反的虚拟;if 从句过去完成,主句 would have + 过去分词;填 would。✓ they would have built the device. ✗ will / must / can:虚拟主句用 would。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp2','choice','{"stem":"\"Handed such ideas, any great power would ___ turned the world upside down.\"(与过去相反的虚拟主句 would ___ done,填 would 与过去分词之间的那个词)","options":["having","had","have","has"],"answer_index":2,"stem_cn":"一旦得到这样的想法,任何大国本会把世界搅个天翻地覆。","explanation_cn":"与过去相反的虚拟主句 would + have + 过去分词;填 would 与过去分词之间的 have。✓ would have turned the world upside down. ✗ has / having / had:此结构用 would have done。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp3','choice','{"stem":"\"In early times, competition with other creatures ___ have been critical.\"(对过去的肯定推测‘一定曾…’,填情态动词)","options":["shall","must","would","does"],"answer_index":1,"stem_cn":"在远古,与别的生物竞争一定曾是生死攸关的。","explanation_cn":"对过去的肯定推测‘一定曾…’= must + have + 过去分词;填 must。✓ must have been critical. ✗ would / shall / does:对过去肯定推测用 must have done。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp3','choice','{"stem":"\"The last rival creature ___ have been the mosquito, now largely subdued.\"(‘一定曾是…’对过去肯定推测,填情态动词)","options":["will","shall","must","does"],"answer_index":2,"stem_cn":"最后一个与人相争的生物一定曾是蚊子,如今已大体被制服。","explanation_cn":"对过去的肯定推测‘一定曾是…’;填 must。✓ must have been the mosquito. ✗ will / shall / does:对过去肯定推测用 must have done。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp3','choice','{"stem":"\"Ideas must have ___ more harm than weapons throughout history.\"(must + have + 过去分词,填‘引起’那个动词的过去分词)","options":["caused","causing","cause","to cause"],"answer_index":0,"stem_cn":"纵观历史,观念造成的伤害一定比武器更多。","explanation_cn":"must + have + 过去分词;填 cause 的过去分词 caused。✓ must have caused more harm. ✗ cause / causing / to cause:have 后用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp4','choice','{"stem":"\"A community conditions you to ___ a degree that destructive thoughts seem impossible.\"(to __ a degree that,‘到如此程度以致’,填 degree 前那个词)","options":["so","too","such","very"],"answer_index":2,"stem_cn":"群体对你的塑造达到如此程度,以致破坏性的念头都显得不可能。","explanation_cn":"to such a degree that,‘到如此程度以致’;degree 前用 such。✓ to such a degree that … ✗ so(接形容词)/ very / too:接名词 degree 用 such。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp4','choice','{"stem":"\"It was ___ a dangerous idea that no one dared to speak it aloud.\"(‘如此(一个)…以致…’,填 a 前那个词)","options":["very","too","so","such"],"answer_index":3,"stem_cn":"那是个如此危险的念头,以致无人敢大声说出。","explanation_cn":"such + a + 名词 + that,‘如此(一个)…以致…’;填 such。✓ such a dangerous idea that … ✗ so / very / too:接名词短语用 such。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp4','choice','{"stem":"\"They had ___ power over minds that free speech could hardly exist.\"(‘如此…以致…’,填名词前那个词)","options":["very","such","too","so"],"answer_index":1,"stem_cn":"他们对人心有如此大的支配力,以致言论自由几乎无法存在。","explanation_cn":"such + 名词 + that;填 such。✓ such power that free speech could hardly exist. ✗ so / very / too:接名词 power 用 such。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp5','choice','{"stem":"\"The competition ___ in biology is a simple struggle for food.\"(过去分词作后置定语,填‘设想/预见’那个动词的过去分词)","options":["envisioned","envisioning","envision","to envision"],"answer_index":0,"stem_cn":"生物学里所设想的那种竞争,是对食物的简单争夺。","explanation_cn":"过去分词作后置定语,表被动完成;填 envision 的过去分词 envisioned。✓ the process envisioned in biology. ✗ envisioning(主动)/ envision / to envision:后置定语用过去分词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp5','choice','{"stem":"\"A few pages ___ to a great power could rewrite history.\"(过去分词作后置定语,填‘递交/交给’那个动词的过去分词)","options":["hand","handing","to hand","handed"],"answer_index":3,"stem_cn":"交到一个大国手里的几页纸,足以改写历史。","explanation_cn":"过去分词作后置定语;填 hand 的过去分词 handed。✓ a few pages handed to a great power. ✗ handing / hand / to hand:后置定语用过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp5','choice','{"stem":"\"The effects ___ by ideas were far worse than those of any weapon.\"(过去分词作后置定语,填‘造成’那个动词的过去分词)","options":["caused","causing","to cause","cause"],"answer_index":0,"stem_cn":"由观念所造成的后果,远比任何武器都严重。","explanation_cn":"过去分词作后置定语;填 cause 的过去分词 caused。✓ the effects caused by ideas. ✗ causing / cause / to cause:后置定语用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp6','choice','{"stem":"\"To argue about or question the truth of something is to ___ it.\"(“争论,质疑”用哪个词)","options":["disturb","dispute","dissolve","distribute"],"answer_index":1,"stem_cn":"就某事争辩或质疑其真伪。","explanation_cn":"就某事争辩或质疑其真伪是 dispute(争论、质疑)。✓ to argue about something is to dispute it. ✗ distribute 分发;✗ disturb 打扰;✗ dissolve 溶解——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp6','choice','{"stem":"\"To bring under control by force or persuasion is to ___.\"(“制服,压制”用哪个词)","options":["subdue","submit","subscribe","substitute"],"answer_index":0,"stem_cn":"用武力或劝说使之服从。","explanation_cn":"用武力或劝说使之服从是 subdue(制服、压制)。✓ to bring under control is to subdue. ✗ subscribe 订阅;✗ submit 提交/屈服;✗ substitute 替代——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',5,'am4_l45_gp6','choice','{"stem":"\"To imagine or form an idea of something is to ___ it.\"(“构想,想象”用哪个词)","options":["receive","deceive","perceive","conceive"],"answer_index":3,"stem_cn":"构想或形成对某物的想法。","explanation_cn":"构想或形成对某物的想法是 conceive(构想、想象)。✓ to imagine something is to conceive it. ✗ receive 收到;✗ deceive 欺骗;✗ perceive 察觉——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',6,NULL,'choice','{"stem":"dispute 的意思是:","options":["忽视","同意","争论,质疑","证实"],"answer_index":2,"explanation_cn":"dispute = 争论、质疑。✓ disputing the ownership of a cave."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',6,NULL,'choice','{"stem":"subdue 的意思是:","options":["释放","制服,压制","服从","激励"],"answer_index":1,"explanation_cn":"subdue = 制服、压制。✓ the mosquito has been largely subdued."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',6,NULL,'choice','{"stem":"envision 的意思是:","options":["遗忘","怀疑","展望,设想","摧毁"],"answer_index":2,"explanation_cn":"envision = 展望、设想。✓ the simple process envisioned in biology."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',6,NULL,'choice','{"stem":"conceive 的意思是:","options":["证明","拒绝","复制","构想,想象"],"answer_index":3,"explanation_cn":"conceive = 构想、想象。✓ difficult to conceive of anything destructive."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',6,NULL,'choice','{"stem":"suffice 的意思是:","options":["超过","足够,足以","缺乏","浪费"],"answer_index":1,"explanation_cn":"suffice = 足够、足以。✓ it will suffice to think of one technology."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',6,NULL,'choice','{"stem":"original 的意思是:","options":["独创的,新颖的","虚假的","普通的","陈旧的"],"answer_index":0,"explanation_cn":"original = 独创的、新颖的。✓ only if we are very original."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',7,NULL,'cloze','{"stem":"第 1 空","context":"Their difference lies not so much in resources ___1___ in belief. In early days, competition ___2___ have been fierce, but that age is over. A few pages of secrets ___3___ have changed history in 1925. Ideas condition us to ___4___ a degree that we can scarcely think outside them.","blank_no":1,"options":["as","than","but","so"],"answer_index":0,"explanation_cn":"not so much A as B,‘与其说A不如说B’;连接 B 用 as。✓ not so much in resources as in belief."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',7,NULL,'cloze','{"stem":"第 2 空","context":"Their difference lies not so much in resources ___1___ in belief. In early days, competition ___2___ have been fierce, but that age is over. A few pages of secrets ___3___ have changed history in 1925. Ideas condition us to ___4___ a degree that we can scarcely think outside them.","blank_no":2,"options":["must","will","shall","does"],"answer_index":0,"explanation_cn":"对过去的肯定推测‘一定曾…’= must + have + 过去分词;填 must。✓ competition must have been fierce."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',7,NULL,'cloze','{"stem":"第 3 空","context":"Their difference lies not so much in resources ___1___ in belief. In early days, competition ___2___ have been fierce, but that age is over. A few pages of secrets ___3___ have changed history in 1925. Ideas condition us to ___4___ a degree that we can scarcely think outside them.","blank_no":3,"options":["would","will","shall","does"],"answer_index":0,"explanation_cn":"与过去事实相反的虚拟,主句用 would + have + 过去分词;填 would。✓ a few pages would have changed history."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',7,NULL,'cloze','{"stem":"第 4 空","context":"Their difference lies not so much in resources ___1___ in belief. In early days, competition ___2___ have been fierce, but that age is over. A few pages of secrets ___3___ have changed history in 1925. Ideas condition us to ___4___ a degree that we can scarcely think outside them.","blank_no":4,"options":["such","so","very","too"],"answer_index":0,"explanation_cn":"to such a degree that,‘到如此程度以致’;degree 前用 such。✓ conditions us to such a degree that …"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',8,NULL,'choice','{"stem":"According to the writer, what is the most important factor in our environment?","options":["The amount of food available","The climate and natural resources","The state of our own minds — the things we believe","The weapons a society owns"],"answer_index":2,"explanation_cn":"录音说:我们环境中最重要的因素,是我们自己心智的状态、我们所相信的东西。✓ state of our minds."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',8,NULL,'choice','{"stem":"Why does the writer say that ideas can be more dangerous than physical weapons?","options":["Because, introduced from outside, a few pages of ideas could change or even destroy a whole society","Because ideas cost more money","Because ideas are heavier than weapons","Because weapons never do any harm"],"answer_index":0,"explanation_cn":"录音说:观念比武器更危险,因为从外部引入的几页观念,就能改变甚至摧毁整个社会。✓ a few pages of ideas."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',8,NULL,'choice','{"stem":"Why are Morocco and California, though similar in climate and latitude, so different today?","options":["Because they are on different continents'' east coasts","Because one has more mosquitoes","Because their natural resources are completely different","Because their development is shaped mainly by what their peoples believe, not by physical conditions"],"answer_index":3,"explanation_cn":"录音说:摩洛哥与加州气候纬度相近却发展迥异,因为塑造它们的主要是人心所信,而非自然条件。✓ shaped by belief."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',9,NULL,'choice','{"stem":"你想说\"它们的差异,与其说源于资源,不如说源于信念\"(not so much A as B):","options":["Their difference lies not so much in resources but in belief.","Their difference lies not so much in resources as in belief.","Their difference lies not so much in resources than in belief.","Their difference lies so much not in resources as in belief."],"answer_index":1,"explanation_cn":"not so much A as B;连接 B 用 as(不用 than、but)、not so much 词序不能乱(不写 so much not)。✓ not so much A as B. 场合:说“与其说A不如说B”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',9,NULL,'choice','{"stem":"你想说\"倘若他们知道那个秘密,本会造出那装置\"(与过去相反的虚拟 would have done):","options":["If they had known the secret, they would have built the device.","If they had known the secret, they will have built the device.","If they had known the secret, they would build the device.","If they knew the secret, they would have built the device."],"answer_index":0,"explanation_cn":"与过去相反的虚拟;if 从句用过去完成 had known(不用 knew)、主句用 would have + 过去分词(不用 would build、不用 will have)。✓ would have built. 场合:说“(与过去事实相反)本会…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',9,NULL,'choice','{"stem":"你想说\"在远古,与别的生物竞争一定曾是生死攸关的\"(must have done 对过去肯定推测):","options":["In early times, competition with other creatures had to be critical.","In early times, competition with other creatures must be critical.","In early times, competition with other creatures must have been critically.","In early times, competition with other creatures must have been critical."],"answer_index":3,"explanation_cn":"must have done 对过去的肯定推测;have been 后接形容词 critical(不用副词 critically)、用 must have been(不用 must be、不用表义务的 had to be)。✓ must have been critical. 场合:对过去的事作肯定推测。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"dispute 的意思是:","options":["证实","忽视","争论,质疑","同意"],"answer_index":2,"explanation_cn":"dispute = 争论、质疑。✓ disputing the ownership of a cave."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"subdue 的意思是:","options":["激励","制服,压制","释放","服从"],"answer_index":1,"explanation_cn":"subdue = 制服、压制。✓ the mosquito has been largely subdued."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"\"Their difference lies not so much in resources ___ in belief.\"(not so much A __ B)","options":["than","but","as","so"],"answer_index":2,"stem_cn":"它们的差异与其说在资源,不如说在信念。","explanation_cn":"not so much A as B;连接 B 用 as。✓ not so much in resources as in belief. ✗ than / but / so。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"\"In early days, competition ___ have been fierce.\"(对过去的肯定推测)","options":["must","will","shall","does"],"answer_index":0,"stem_cn":"早年间竞争一定曾很激烈。","explanation_cn":"对过去的肯定推测‘一定曾…’= must + have + 过去分词;填 must。✓ competition must have been fierce. ✗ will / shall / does。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"\"look on\" 的意思是:","options":["照顾…","旁观,观望","依靠…","寻找…"],"answer_index":1,"explanation_cn":"look on = 旁观、观望。✓ someone looking on from outside."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"\"turn upside down\" 的意思是:","options":["修好…","藏起…","复制…","彻底颠覆,搅乱"],"answer_index":3,"explanation_cn":"turn upside down = 彻底颠覆、搅乱。✓ could turn the world upside down."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"Why is the competition of man against man no longer a simple struggle for food?","options":["Because the environment that shapes us is no longer mainly physical but is conditioned by what we believe","Because there is now unlimited food","Because food no longer matters to anyone","Because people no longer compete at all"],"answer_index":0,"passage":"In man''s early days, his competition with other creatures must have been a matter of life and death. But that phase of our development is long over. Indeed, we now lack all practice in dealing with primitive conditions; without modern tools, I am quite sure I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think I stand alone. The last creature to compete seriously with man was the mosquito — and even the mosquito has been largely subdued by attention to drainage and by chemical sprays. Competition among ourselves, person against person and community against community, still persists, however, and it is as fierce as it ever was. Yet the competition of man against man is not the simple process envisioned in biology. It is not a plain struggle for a fixed amount of food fixed by the physical world, because the environment that now shapes our development is no longer essentially physical. Our environment is chiefly conditioned by the things we believe. Morocco and California are patches of the Earth at very similar latitudes, both on the west coasts of continents, with similar climates and probably rather similar natural resources; yet their present development is wholly different — not so much because of any difference in the land as because of a difference in the minds of the people who live there. The most important factor in our environment is the state of our own minds. It is well known that where one culture has met another, the most destructive effects have often come not from physical weapons but from ideas. Ideas can be dangerous. A powerful authority of earlier ages understood this well: fearing certain beliefs, it branded those who held them heretics and did all it could to silence them. Indeed, the very concept of free speech can flourish in a society only because, when you are inside a community, you are conditioned by its conventions to such a degree that it is very difficult to conceive of anything truly destructive. It is usually someone looking on from outside who can inject the dangerous thought. I do not doubt that it would be possible to introduce into the modern world ideas that could utterly transform it. Perhaps it will suffice to think of a single dangerous technology, such as the nuclear bomb: a few pages of information, handed to any of the major world powers around the year 1925, might well have been enough to change the whole course of world history. It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas could turn the present-day world upside down, or even destroy it. Outside the particular patterns to which our brains are conditioned, we can think only a very little way — and then only if we are very original.","explanation_cn":"课文说:人与人的竞争不再是对食物的简单争夺,因为塑造我们的环境已不再主要是物质的,而由我们所信之物决定。✓ environment conditioned by belief."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"What example does the writer use to show how a small amount of information could change history?","options":["A map of hidden treasure","A single new weapon given to every nation","A list of the world''s mosquitoes","A few pages of ideas handed to a world power in 1925 could have altered the course of events"],"answer_index":3,"passage":"In man''s early days, his competition with other creatures must have been a matter of life and death. But that phase of our development is long over. Indeed, we now lack all practice in dealing with primitive conditions; without modern tools, I am quite sure I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think I stand alone. The last creature to compete seriously with man was the mosquito — and even the mosquito has been largely subdued by attention to drainage and by chemical sprays. Competition among ourselves, person against person and community against community, still persists, however, and it is as fierce as it ever was. Yet the competition of man against man is not the simple process envisioned in biology. It is not a plain struggle for a fixed amount of food fixed by the physical world, because the environment that now shapes our development is no longer essentially physical. Our environment is chiefly conditioned by the things we believe. Morocco and California are patches of the Earth at very similar latitudes, both on the west coasts of continents, with similar climates and probably rather similar natural resources; yet their present development is wholly different — not so much because of any difference in the land as because of a difference in the minds of the people who live there. The most important factor in our environment is the state of our own minds. It is well known that where one culture has met another, the most destructive effects have often come not from physical weapons but from ideas. Ideas can be dangerous. A powerful authority of earlier ages understood this well: fearing certain beliefs, it branded those who held them heretics and did all it could to silence them. Indeed, the very concept of free speech can flourish in a society only because, when you are inside a community, you are conditioned by its conventions to such a degree that it is very difficult to conceive of anything truly destructive. It is usually someone looking on from outside who can inject the dangerous thought. I do not doubt that it would be possible to introduce into the modern world ideas that could utterly transform it. Perhaps it will suffice to think of a single dangerous technology, such as the nuclear bomb: a few pages of information, handed to any of the major world powers around the year 1925, might well have been enough to change the whole course of world history. It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas could turn the present-day world upside down, or even destroy it. Outside the particular patterns to which our brains are conditioned, we can think only a very little way — and then only if we are very original.","explanation_cn":"课文说:作者举例,几页观念若在1925年交到某大国手里,本可改变历史进程。✓ a few pages in 1925."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"What finally subdued the mosquito, the last creature to compete with man?","options":["Attention to drainage and the use of chemical sprays","Modern weapons","The building of cities","A change in climate"],"answer_index":0,"audio":"In man''s early days, his competition with other creatures must have been a matter of life and death. But that phase of our development is long over. Indeed, we now lack all practice in dealing with primitive conditions; without modern tools, I am quite sure I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think I stand alone. The last creature to compete seriously with man was the mosquito — and even the mosquito has been largely subdued by attention to drainage and by chemical sprays. Competition among ourselves, person against person and community against community, still persists, however, and it is as fierce as it ever was. Yet the competition of man against man is not the simple process envisioned in biology. It is not a plain struggle for a fixed amount of food fixed by the physical world, because the environment that now shapes our development is no longer essentially physical. Our environment is chiefly conditioned by the things we believe. Morocco and California are patches of the Earth at very similar latitudes, both on the west coasts of continents, with similar climates and probably rather similar natural resources; yet their present development is wholly different — not so much because of any difference in the land as because of a difference in the minds of the people who live there. The most important factor in our environment is the state of our own minds. It is well known that where one culture has met another, the most destructive effects have often come not from physical weapons but from ideas. Ideas can be dangerous. A powerful authority of earlier ages understood this well: fearing certain beliefs, it branded those who held them heretics and did all it could to silence them. Indeed, the very concept of free speech can flourish in a society only because, when you are inside a community, you are conditioned by its conventions to such a degree that it is very difficult to conceive of anything truly destructive. It is usually someone looking on from outside who can inject the dangerous thought. I do not doubt that it would be possible to introduce into the modern world ideas that could utterly transform it. Perhaps it will suffice to think of a single dangerous technology, such as the nuclear bomb: a few pages of information, handed to any of the major world powers around the year 1925, might well have been enough to change the whole course of world history. It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas could turn the present-day world upside down, or even destroy it. Outside the particular patterns to which our brains are conditioned, we can think only a very little way — and then only if we are very original.","explanation_cn":"课文说:最后一个与人相争的蚊子,是靠整治排水与化学喷剂而被制服的。✓ drainage and sprays."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l45',10,NULL,'choice','{"stem":"According to the writer, how far can our minds think beyond the patterns we are conditioned to?","options":["Only when we use weapons","As far as we like, with no limits","Only a very little way, and then only if we are very original","Not at all, ever"],"answer_index":2,"audio":"In man''s early days, his competition with other creatures must have been a matter of life and death. But that phase of our development is long over. Indeed, we now lack all practice in dealing with primitive conditions; without modern tools, I am quite sure I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think I stand alone. The last creature to compete seriously with man was the mosquito — and even the mosquito has been largely subdued by attention to drainage and by chemical sprays. Competition among ourselves, person against person and community against community, still persists, however, and it is as fierce as it ever was. Yet the competition of man against man is not the simple process envisioned in biology. It is not a plain struggle for a fixed amount of food fixed by the physical world, because the environment that now shapes our development is no longer essentially physical. Our environment is chiefly conditioned by the things we believe. Morocco and California are patches of the Earth at very similar latitudes, both on the west coasts of continents, with similar climates and probably rather similar natural resources; yet their present development is wholly different — not so much because of any difference in the land as because of a difference in the minds of the people who live there. The most important factor in our environment is the state of our own minds. It is well known that where one culture has met another, the most destructive effects have often come not from physical weapons but from ideas. Ideas can be dangerous. A powerful authority of earlier ages understood this well: fearing certain beliefs, it branded those who held them heretics and did all it could to silence them. Indeed, the very concept of free speech can flourish in a society only because, when you are inside a community, you are conditioned by its conventions to such a degree that it is very difficult to conceive of anything truly destructive. It is usually someone looking on from outside who can inject the dangerous thought. I do not doubt that it would be possible to introduce into the modern world ideas that could utterly transform it. Perhaps it will suffice to think of a single dangerous technology, such as the nuclear bomb: a few pages of information, handed to any of the major world powers around the year 1925, might well have been enough to change the whole course of world history. It is a strange thought, but I believe a correct one, that twenty or thirty pages of ideas could turn the present-day world upside down, or even destroy it. Outside the particular patterns to which our brains are conditioned, we can think only a very little way — and then only if we are very original.","explanation_cn":"课文说:在被塑造的既定模式之外,我们只能想出极有限的一点点,且惟有极富原创性时才行。✓ only a little way, if original."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l46',4,8,46,'Hobbies','业余爱好','the + 比较级, the + 比较级(越…越…)、it is no use doing(做…没有用)、those who 定语从句、情态动词的被动(must be done)、不定式作目的状语(To do…, 主句)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 Winston Churchill《Painting as a Pastime》一段论‘培养爱好以缓解精神紧张’的随笔,系版权作品——已用 100% 原创行文复述其观点、无引用原句;词表按 CONSTITUTION 第0章取现代可教的12词,舍弃古旧文学词 sedulously/vivify/caprice/satiation/clatter 等,详见 DECISIONS;题材=心理调适/生活随笔·无害;美语化 favor/favored/laborer;第四册第46课)','一位有天赋的心理学家曾说,烦恼是心灵的一阵痉挛:头脑抓住某样东西,怎么也不肯松手。跟处于这种状态的头脑争论是徒劳的——的确,意志越强,这份努力越是徒劳。你没法命令烦恼离开,只能把别的东西轻轻地引进它紧攥的手里。若这别的东西选得得当,若它真带来另一片兴趣天地的启迪,那么渐渐地——往往还相当快地——那旧有的、过分的紧张便松开了,休整与修复的过程就此开始。所以,对任何肩上担着责任的人来说,培养一种爱好、培养新的兴趣,是头等重要的策略。可这不是一下午就能临时凑成、也不是单凭意志一声令下就能唤起的事。别样兴趣的生长很慢。种子须精心挑选,须落在好土上,须耐心照料,好让富有生机的果实在需要时正好在手边。要想真正幸福、真正稳当,一个人应当有两三种爱好,而且每一种都得是真的。到了晚年才宣布‘从今以后我要对这个或那个感兴趣’,是没有用的;这种努力只会加剧它本想缓解的那份紧张。一个人可以对与日常工作无关的题目积累渊博的知识,却几乎从中得不到宽慰。干你喜欢的事没有用;你得学会喜欢你所干的事。大而言之,人可以分为三类:被累死的人、被愁死的人、被闷死的人。对于流汗苦干了一周的体力劳动者,周六下午一场足球或棒球是真正的释放;可是,让为大事操劳忧虑了六天的政界人士或商人,周末再去为琐事操心,却是没有用的。至于那些能满足每一个心血来潮、几乎能对一切所欲之物随手取得的幸运少数,一种新的乐趣不过是又朝厌烦迈进了一步。他们徒劳地从一处奔到另一处,指望单凭奔忙就甩掉紧随脚后的沉闷。讲道理、有用处的人分作两类:一类把工作与消遣严格分开,一类的工作与消遣合而为一。前一类人居多,他们有其补偿——长时间的劳作带来的不仅是生计,还有对最简单乐趣的强烈胃口。然而,命运的宠儿属于第二类。对他们来说,工作的时辰永远不够长;每一天都是假日,而假日本身反倒像是对一桩引人入胜的事业的一种打断。可即便如此,这两类人都需要时不时地把当天的工作从头脑中驱走,让气氛的一换来使自己恢复精神。','{"q":"Listen and answer — Who, according to the writer, are ''Fortune''s favored children''?","options":["People for whom work is itself a pleasure, so their working hours are never long enough","People who never have to work at all","People who have the most expensive hobbies","People who worry about nothing"],"answer_index":0}'::jsonb,'{"title":"the + 比较级, the + 比较级 / it is no use doing / those who 定语从句 / 情态动词被动 must be done / 不定式作目的状语","intro":"①the + 比较级…, the + 比较级…:‘越…越…’,两个分句都以 the 开头,形容词/副词都用比较级。②It is no use + 动名词:‘做…没有用’,use 后必须接 -ing,不接 to do。③those who + 从句:‘…的那些人’,who 指人作主语;whose 表所属。④情态动词的被动:情态动词 + be + 过去分词(the seeds must be chosen)。⑤不定式作目的状语:To do…, 主句(‘为了…而…’),常置于句首。","table":{"headers":["用法","结构","例子"],"rows":[["the+比较级,the+比较级","the 比较级…, the 比较级…","the stronger the will, the more futile the effort"],["it is no use doing","it is no use + 动名词","it is no use arguing with the mind"],["those who 定从","those who + 谓语","those who are worried to death"],["情态动词被动","情态动词 + be + 过去分词","the seeds must be chosen with care"],["不定式作目的状语","To do …, 主句","To be really happy, one ought to have hobbies"]]},"specialRules":[{"rule":"the + 比较级 结构里,形容词/副词一律用比较级(more futile、greater),不能用原级或最高级;两个分句都以 the 开头。","mark":"the + 比较级, the + 比较级"},{"rule":"it is no use 后一律接动名词(doing),不接不定式(to do)。同义说法:there is no use doing。","mark":"it is no use doing"},{"rule":"美式拼写:favor / favored(英式 favour / favoured)、laborer(英式 labourer)。本课已按美语写。","mark":"favor / laborer"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l46',1,NULL,'A gifted psychologist once remarked that worry is a kind of spasm of the mind: the mind seizes on something and simply will not let it go. Arguing with a mind in that state is futile — indeed, the stronger the will, the more futile the effort. You cannot order the worry out; you can only coax something else gently into its grip. And if that something else is well chosen, if it truly carries the illumination of a fresh field of interest, then little by little the old, excessive tension loosens, and the work of recovery begins.','一位有天赋的心理学家曾说,烦恼是心灵的一阵痉挛:头脑抓住某样东西,怎么也不肯松手。跟处于这种状态的头脑争论是徒劳的——的确,意志越强,这份努力越是徒劳。你没法命令烦恼离开,只能把别的东西轻轻地引进它紧攥的手里。若这别的东西选得得当,若它真带来另一片兴趣天地的启迪,那么渐渐地,那旧有的、过分的紧张便松开了,休整与修复的过程就此开始。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l46',2,NULL,'For anyone whose days are crowded with responsibility, the cultivation of a hobby and of new interests is therefore a policy of the first importance. But it is not a thing that can be improvised in an afternoon, or summoned up by a mere command of the will. The growth of alternative interests is slow. The seeds must be chosen with care; they must be planted in good ground; they must be tended patiently, if the living fruit is to be ready when it is wanted.','所以,对任何肩上担着责任的人来说,培养一种爱好、培养新的兴趣,是头等重要的策略。可这不是一下午就能临时凑成、也不是单凭意志一声令下就能唤起的事。别样兴趣的生长很慢。种子须精心挑选,须落在好土上,须耐心照料,好让富有生机的果实在需要时正好在手边。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l46',3,NULL,'To be really happy and really steady, a person ought to have two or three hobbies, and every one of them must be real. It is no use waiting until late in life to announce, ''From now on I will take an interest in this or that.'' Such an effort only aggravates the very strain it was meant to relieve. It is no use doing what you like; you have to learn to like what you do.','要想真正幸福、真正稳当,一个人应当有两三种爱好,而且每一种都得是真的。到了晚年才宣布‘从今以后我要对这个或那个感兴趣’,是没有用的;这种努力只会加剧它本想缓解的那份紧张。干你喜欢的事没有用;你得学会喜欢你所干的事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l46',4,NULL,'Broadly speaking, people may be divided into three classes: those who are worked to death, those who are worried to death, and those who are bored to death. For the laborer who has sweated through a hard week, an afternoon game of football or baseball is a real release. But it is no use asking the politician or the businessman, who has been worrying over grave matters for six days, to spend the weekend worrying over trifling ones instead.','大而言之,人可以分为三类:被累死的人、被愁死的人、被闷死的人。对于流汗苦干了一周的体力劳动者,周六下午一场足球或棒球是真正的释放;可是,让为大事操劳忧虑了六天的政界人士或商人,周末再去为琐事操心,却是没有用的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l46',5,NULL,'As for the fortunate few who can gratify every whim, a new pleasure is only one more step toward boredom. Reasonable, useful people fall into two classes: those who keep work and play strictly apart, and those for whom the two are one. Yet Fortune''s favored children belong to the second class. For them the working hours are never long enough; each day is a holiday. And yet both classes need, at intervals, to banish the day''s work from their minds and let a change of atmosphere refresh them.','至于那些能满足每一个心血来潮的幸运少数,一种新的乐趣不过是又朝厌烦迈进了一步。讲道理、有用处的人分作两类:一类把工作与消遣严格分开,一类的工作与消遣合而为一。然而,命运的宠儿属于第二类。对他们来说,工作的时辰永远不够长,每一天都是假日。可即便如此,这两类人都需要时不时地把当天的工作从头脑中驱走,让气氛的一换来使自己恢复精神。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
