INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l46','it is no use doing','',NULL,'/ɪt ɪz noʊ juːs ˈduːɪŋ/','It is no use arguing with a worried mind.','跟烦恼的头脑争论是没有用的。','It is no use crying over a lost chance.','为失去的机会哭泣是没有用的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l46','be divided into','',NULL,'/bi dɪˈvaɪdɪd ˈɪntə/','People may be divided into three classes.','人可以分为三类。','The book is divided into five parts.','这本书分为五个部分。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l46','at intervals','',NULL,'/æt ˈɪntərvəlz/','Both classes need, at intervals, to rest the mind.','两类人都需要时不时地让头脑休息。','Trees were planted at intervals along the road.','沿路每隔一段就种着树。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l46','let go of','',NULL,'/let ɡoʊ ʌv/','The worried mind will not let go of its object.','烦恼的头脑不肯放开它抓住的东西。','You have to let go of the past.','你得放下过去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp1','choice','{"stem":"\"The ___ the will, the more futile the struggle against a worry.\"(‘越…越…’句式,第一分句填 strong 的比较级)","options":["strongly","strong","strongest","stronger"],"answer_index":3,"stem_cn":"意志越强,与烦恼的搏斗越是徒劳。","explanation_cn":"‘越…越…’= the + 比较级…, the + 比较级…;第一分句填 strong 的比较级 stronger。✓ the stronger the will, the more futile the effort. ✗ strong(原级)/ strongest(最高级)/ strongly(副词):此结构用比较级。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp1','choice','{"stem":"\"The ___ absorbing the hobby, the sooner the mind lets go.\"(‘越…越…’,填第一个 the 之后表示比较的词)","options":["much","very","more","most"],"answer_index":2,"stem_cn":"爱好越是引人入胜,头脑越快松开。","explanation_cn":"the + 比较级,the + 比较级;absorbing 的比较级用 more absorbing,填 more。✓ the more absorbing the hobby. ✗ most(最高级)/ very / much:比较级用 more。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp1','choice','{"stem":"\"The longer he worried, the ___ his tension grew.\"(‘越…越…’,第二分句 the 后用形容词的比较级)","options":["greater","greatest","great","greatly"],"answer_index":0,"stem_cn":"他忧虑得越久,紧张就越发严重。","explanation_cn":"the + 比较级,the + 比较级;第二分句用 great 的比较级 greater。✓ the greater his tension grew. ✗ great(原级)/ greatest(最高级)/ greatly(副词):此处要形容词比较级。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp2','choice','{"stem":"\"It is no ___ arguing with a mind in this state.\"(‘做…没有用’的固定句式,填 no 之后、动名词之前的那个名词)","options":["useful","use","using","used"],"answer_index":1,"stem_cn":"跟处于这种状态的头脑争论是没有用的。","explanation_cn":"‘做…没有用’= it is no use + 动名词;固定说法填名词 use。✓ it is no use arguing. ✗ used / using / useful:固定结构是 no use。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp2','choice','{"stem":"\"It is no use ___ what you like; you must like what you do.\"(‘做…没用’,use 后接动名词,填 do 的 -ing 形式)","options":["doing","done","do","to do"],"answer_index":0,"stem_cn":"干你喜欢的事没有用;你必须喜欢你所干的事。","explanation_cn":"it is no use 后接动名词;填 do 的 -ing 形式 doing。✓ it is no use doing what you like. ✗ to do / do / done:use 后一律用 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp2','choice','{"stem":"\"It is no use ___ until late in life to start a hobby.\"(‘…没有用’,use 后接动名词,填 wait 的 -ing 形式)","options":["waited","wait","to wait","waiting"],"answer_index":3,"stem_cn":"等到晚年才开始培养爱好是没有用的。","explanation_cn":"it is no use 后接动名词;填 wait 的 -ing 形式 waiting。✓ it is no use waiting until late in life. ✗ to wait / wait / waited:use 后一律用 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp3','choice','{"stem":"\"People fall into three classes: ___ who are worked to death, and others.\"(‘…的那些人’,填 who 前面表示‘那些人’的先行词)","options":["which","those","what","whom"],"answer_index":1,"stem_cn":"人分为三类:被累死的那些人,以及其他人。","explanation_cn":"‘…的那些人’= those who;先行词用 those,填 who 前的 those。✓ those who are worked to death. ✗ which / whom / what:指人的那些人用 those。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp3','choice','{"stem":"\"Fortune''s favored children are those ___ love their work.\"(定语从句,先行词 those 指人作主语,填关系词)","options":["whom","whose","which","who"],"answer_index":3,"stem_cn":"命运的宠儿是那些热爱自己工作的人。","explanation_cn":"定语从句先行词 those 指人、在从句里作主语,用关系代词 who。✓ those who love their work. ✗ which(指物)/ whom(宾格)/ whose(所属):作主语指人用 who。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp3','choice','{"stem":"\"They are the people ___ hobbies are all real.\"(定语从句,表‘他们的爱好’的所属关系,填关系词)","options":["who","which","whose","whom"],"answer_index":2,"stem_cn":"他们是那些爱好全都真实的人。","explanation_cn":"定语从句表‘他们的爱好’这种所属关系,用 whose。✓ the people whose hobbies are all real. ✗ who(作主语)/ which / whom:表所属用 whose。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp4','choice','{"stem":"\"The seeds of a new interest must ___ chosen with care.\"(情态动词的被动:情态动词 + ___ + 过去分词,填 must 与过去分词之间那个词)","options":["been","being","to be","be"],"answer_index":3,"stem_cn":"新兴趣的种子必须精心挑选。","explanation_cn":"情态动词的被动 = 情态动词 + be + 过去分词;must 后填 be。✓ must be chosen with care. ✗ been / being / to be:情态动词后接原形 be。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp4','choice','{"stem":"\"A worry cannot be ___ by force of will alone.\"(情态动词的被动 be + 过去分词,填 banish 的过去分词)","options":["to banish","banished","banish","banishing"],"answer_index":1,"stem_cn":"单靠意志无法驱除一桩烦恼。","explanation_cn":"情态动词被动 be + 过去分词;填 banish 的过去分词 banished。✓ cannot be banished by will alone. ✗ banish / banishing / to banish:be 后用过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp4','choice','{"stem":"\"People may be ___ into three classes.\"(情态动词的被动 be + 过去分词,填 divide 的过去分词)","options":["to divide","divide","dividing","divided"],"answer_index":3,"stem_cn":"人可以被分为三类。","explanation_cn":"情态动词被动 be + 过去分词;填 divide 的过去分词 divided。✓ may be divided into three classes. ✗ divide / dividing / to divide:be 后用过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp5','choice','{"stem":"\"___ really happy and steady, one ought to have a few real hobbies.\"(不定式作目的状语置于句首,填‘为了…’的不定式形式)","options":["To be","Being","For be","Be"],"answer_index":0,"stem_cn":"要想真正幸福、稳当,一个人应当有几种真正的爱好。","explanation_cn":"不定式作目的状语置于句首,‘为了…’;填 To be。✓ To be really happy, one ought to have hobbies. ✗ Being(动名词)/ Be / For be:表目的用不定式 To do。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp5','choice','{"stem":"\"He took up painting ___ escape the strain of office life.\"(不定式作目的状语,填‘为了’那个词)","options":["for","so","to","that"],"answer_index":2,"stem_cn":"他开始画画,为的是逃离办公室生活的紧张。","explanation_cn":"不定式作目的状语,‘为了逃离…’;填 to。✓ took up painting to escape the strain. ✗ for(后不接动词原形)/ that / so:目的用 to + 动词原形。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp5','choice','{"stem":"\"She reads novels at night ___ banish the worries of the day.\"(不定式作目的状语,填‘为了’那个词)","options":["to","with","of","for"],"answer_index":0,"stem_cn":"她夜里读小说,为的是驱走白天的烦恼。","explanation_cn":"不定式作目的状语,‘为了驱走…’;填 to。✓ reads novels to banish the worries. ✗ for / of / with:目的用 to + 动词原形。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp6','choice','{"stem":"\"Something that has no effect and leads nowhere is ___.\"(“徒劳的,无效的”用哪个词)","options":["fertile","fatal","futile","final"],"answer_index":2,"stem_cn":"毫无效果、毫无结果的。","explanation_cn":"毫无效果、毫无结果的是 futile(徒劳的、无效的)。✓ a futile effort. ✗ fertile 肥沃的;✗ fatal 致命的;✗ final 最后的——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp6','choice','{"stem":"\"To make a bad situation worse is to ___ it.\"(“加剧,使恶化”用哪个词)","options":["aggregate","aggravate","agitate","appreciate"],"answer_index":1,"stem_cn":"使糟糕的局面变得更糟。","explanation_cn":"使糟糕的局面变得更糟是 aggravate(加剧、使恶化)。✓ aggravate the strain. ✗ appreciate 欣赏;✗ aggregate 聚合;✗ agitate 搅动/使不安——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',5,'am4_l46_gp6','choice','{"stem":"\"To drive an unwanted thought out of your mind is to ___ it.\"(“驱除,消除”用哪个词)","options":["banish","punish","vanish","polish"],"answer_index":0,"stem_cn":"把不想要的念头赶出脑海。","explanation_cn":"把不想要的念头赶出脑海是 banish(驱除、消除)。✓ banish the thought from your mind. ✗ vanish 消失(不及物);✗ punish 惩罚;✗ polish 擦亮——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',6,NULL,'choice','{"stem":"futile 的意思是:","options":["容易的","成功的","徒劳的,无效的","必要的"],"answer_index":2,"explanation_cn":"futile = 徒劳的、无效的。✓ the more futile the effort."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',6,NULL,'choice','{"stem":"aggravate 的意思是:","options":["加剧,使恶化","缓解,减轻","忽视,无视","治愈,修复"],"answer_index":0,"explanation_cn":"aggravate = 加剧、使恶化。✓ such an effort only aggravates the strain."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',6,NULL,'choice','{"stem":"gratify 的意思是:","options":["激怒,惹恼","使满足,使高兴","拒绝,回绝","欺骗,蒙蔽"],"answer_index":1,"explanation_cn":"gratify = 使满足、使高兴。✓ the few who can gratify every whim."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',6,NULL,'choice','{"stem":"boredom 的意思是:","options":["恐惧,害怕","满足,充实","兴奋,激动","厌烦,无聊"],"answer_index":3,"explanation_cn":"boredom = 厌烦、无聊。✓ one more step toward boredom."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',6,NULL,'choice','{"stem":"absorbing 的意思是:","options":["引人入胜的","简单的","令人厌烦的","可怕的"],"answer_index":0,"explanation_cn":"absorbing = 引人入胜的。✓ an interruption of an absorbing pursuit."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',6,NULL,'choice','{"stem":"banish 的意思是:","options":["加强,巩固","驱除,消除","欢迎,接纳","保留,留存"],"answer_index":1,"explanation_cn":"banish = 驱除、消除。✓ to banish the day''s work from their minds."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',7,NULL,'cloze','{"stem":"第 1 空","context":"A worried mind will not let go, and the stronger the will, ___1___ more futile the struggle. It is no ___2___ ordering the worry out; a fresh interest must ___3___ chosen instead. To stay steady, a person ought ___4___ keep two or three real hobbies.","blank_no":1,"options":["the","a","so","much"],"answer_index":0,"explanation_cn":"the + 比较级,the + 比较级;第二分句以 the 领起。✓ the stronger the will, the more futile the struggle."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',7,NULL,'cloze','{"stem":"第 2 空","context":"A worried mind will not let go, and the stronger the will, ___1___ more futile the struggle. It is no ___2___ ordering the worry out; a fresh interest must ___3___ chosen instead. To stay steady, a person ought ___4___ keep two or three real hobbies.","blank_no":2,"options":["use","used","using","useful"],"answer_index":0,"explanation_cn":"‘做…没有用’= it is no use + 动名词;填 use。✓ it is no use ordering the worry out."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',7,NULL,'cloze','{"stem":"第 3 空","context":"A worried mind will not let go, and the stronger the will, ___1___ more futile the struggle. It is no ___2___ ordering the worry out; a fresh interest must ___3___ chosen instead. To stay steady, a person ought ___4___ keep two or three real hobbies.","blank_no":3,"options":["be","been","being","to be"],"answer_index":0,"explanation_cn":"情态动词被动 must be + 过去分词;填 be。✓ a fresh interest must be chosen."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',7,NULL,'cloze','{"stem":"第 4 空","context":"A worried mind will not let go, and the stronger the will, ___1___ more futile the struggle. It is no ___2___ ordering the worry out; a fresh interest must ___3___ chosen instead. To stay steady, a person ought ___4___ keep two or three real hobbies.","blank_no":4,"options":["to","for","that","of"],"answer_index":0,"explanation_cn":"ought to + 动词原形;填 to。✓ ought to keep two or three real hobbies."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',8,NULL,'choice','{"stem":"Who, according to the writer, are ''Fortune''s favored children''?","options":["People who never have to work at all","People who can buy any hobby they like","People for whom work is itself a pleasure, so their working hours are never long enough","People who have no worries of any kind"],"answer_index":2,"explanation_cn":"录音说:命运的宠儿是那种工作本身即快乐的人,他们的工作时辰永远嫌不够长。✓ work is a pleasure."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',8,NULL,'choice','{"stem":"Why does the writer say it is no use simply telling a worried person to relax?","options":["Because relaxing is against the law","Because worried people never listen to advice","Because a hobby can be improvised in a single afternoon","Because the stronger the will, the more futile the effort; the mind can only be coaxed onto something else"],"answer_index":3,"explanation_cn":"录音说:光叫人放松没用,因为意志越强越徒劳,只能把别的东西轻轻引进头脑。✓ coax something else in."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',8,NULL,'choice','{"stem":"Into which three classes does the writer say people may be divided?","options":["The rich, the poor, and the middle class","Those worked to death, those worried to death, and those bored to death","Workers, students, and retirees","The happy, the sad, and the angry"],"answer_index":1,"explanation_cn":"录音说:人大致分三类——被累死的、被愁死的、被闷死的。✓ three classes."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',9,NULL,'choice','{"stem":"你想说\"越是硬逼自己别担心,越是徒劳\"(the + 比较级, the + 比较级):","options":["The hard you try to stop worrying, the more futile it is.","The harder you try to stop worrying, more futile it is.","The harder you try to stop worrying, the more futile it is.","Harder you try to stop worrying, the more futile it is."],"answer_index":2,"explanation_cn":"‘越…越…’两个分句都要以 the 领起、都用比较级(harder、more futile),词序不能乱、不能漏第二个 the。✓ The harder…, the more futile… 场合:说“越…就越…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',9,NULL,'choice','{"stem":"你想说\"跟处于这种状态的头脑争论是没有用的\"(it is no use doing):","options":["It is no use arguing with a mind in this state.","It has no use arguing with a mind in this state.","It is no use to argue with a mind in this state.","It is no use argue with a mind in this state."],"answer_index":0,"explanation_cn":"‘做…没有用’后面接 -ing(arguing),不接 to do、不接原形;固定说 it is no use(不是 it has no use)。✓ it is no use arguing. 场合:说“做某事没有用”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',9,NULL,'choice','{"stem":"你想说\"要想真正幸福,一个人应该有两三种真正的爱好\"(不定式作目的状语):","options":["To be really happy, one ought have two or three real hobbies.","Be really happy, one ought to have two or three real hobbies.","For being really happy, one ought to have two or three real hobbies.","To be really happy, one ought to have two or three real hobbies."],"answer_index":3,"explanation_cn":"表目的用 To do 放句首(不用 For being);ought 后要接 to have(不省 to)。✓ To be really happy, one ought to have… 场合:说“为了…,应该…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"futile 的意思是:","options":["短暂的","有效的,管用的","徒劳的,无效的","必要的"],"answer_index":2,"explanation_cn":"futile = 徒劳的、无效的。✓ the more futile the effort."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"gratify 的意思是:","options":["使满足,使高兴","使失望","使困惑","使疲惫"],"answer_index":0,"explanation_cn":"gratify = 使满足、使高兴。✓ can gratify every whim."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"\"The seeds of interest must ___ chosen with care.\"(情态动词的被动)","options":["being","to be","be","been"],"answer_index":2,"stem_cn":"兴趣的种子必须精心挑选。","explanation_cn":"情态动词被动 must be + 过去分词;填 be。✓ the seeds must be chosen with care. ✗ been / being / to be:情态动词后接原形 be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"\"It is no ___ doing what you like; you must like what you do.\"(‘做…没有用’)","options":["use","useful","using","used"],"answer_index":0,"stem_cn":"做你喜欢的事没有用;你必须喜欢你所做的事。","explanation_cn":"‘做…没有用’= it is no use + 动名词;填 use。✓ it is no use doing what you like. ✗ used / using / useful:固定结构是 no use。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"\"it is no use doing\" 的意思是:","options":["做…很值得","做…很容易","做…很危险","做…是没有用的"],"answer_index":3,"explanation_cn":"it is no use doing = 做…是没有用的。✓ it is no use arguing with a worried mind."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"\"banish ... from one''s mind\" 的意思是:","options":["把…大声说出","把…从脑中驱走","把…牢记在心","把…写下来"],"answer_index":1,"explanation_cn":"banish … from one''s mind = 把…从脑中驱走。✓ banish the day''s work from their minds."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"According to the writer, why can a hobby not be improvised in a single afternoon?","options":["Because the growth of alternative interests is slow; the seeds must be chosen, planted, and tended patiently","Because no one has any free afternoons","Because only children are allowed hobbies","Because hobbies are always expensive"],"answer_index":0,"passage":"A gifted psychologist once remarked that worry is a kind of spasm of the mind: the mind seizes on something and simply will not let it go. Arguing with a mind in that state is futile — indeed, the stronger the will, the more futile the effort. You cannot order the worry out; you can only coax something else gently into its grip. And if that something else is well chosen, if it truly carries the illumination of a fresh field of interest, then little by little the old, excessive tension loosens, and the work of recovery begins. For anyone whose days are crowded with responsibility, the cultivation of a hobby and of new interests is therefore a policy of the first importance. But it is not a thing that can be improvised in an afternoon, or summoned up by a mere command of the will. The growth of alternative interests is slow. The seeds must be chosen with care; they must be planted in good ground; they must be tended patiently, if the living fruit is to be ready when it is wanted. To be really happy and really steady, a person ought to have two or three hobbies, and every one of them must be real. It is no use waiting until late in life to announce, ''From now on I will take an interest in this or that.'' Such an effort only aggravates the very strain it was meant to relieve. A man may gather great knowledge of subjects far from his daily work and still draw almost no comfort from it. It is no use doing what you like; you have to learn to like what you do. Broadly speaking, people may be divided into three classes: those who are worked to death, those who are worried to death, and those who are bored to death. For the laborer who has sweated through a hard week, an afternoon game of football or baseball is a real release. But it is no use asking the politician or the businessman, who has been worrying over grave matters for six days, to spend the weekend worrying over trifling ones instead. As for the fortunate few who can gratify every whim and lay their hands on almost anything they desire, a new pleasure is only one more step toward boredom. In vain they rush from place to place, hoping that sheer motion will outrun the dullness at their heels. Reasonable, useful people fall into two classes: those who keep work and play strictly apart, and those for whom the two are one. The first class is the larger, and it has its compensations — the long hours bring not only a living but a keen appetite for the simplest pleasures. Yet Fortune''s favored children belong to the second class. For them the working hours are never long enough; each day is a holiday, and holidays themselves feel like an interruption of an absorbing pursuit. And yet both classes need, at intervals, to banish the day''s work from their minds and let a change of atmosphere refresh them.","explanation_cn":"课文说:爱好没法一下午临时凑成,因为别样兴趣生长很慢,种子须精心挑选、播种、耐心照料。✓ slow growth."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"Why is it no use asking an overworked politician to spend the weekend on trifling worries?","options":["Because trifling worries are illegal","Because he prefers to keep working all weekend","Because he has already been worrying over grave matters all week and needs a real change, not more worry","Because politicians are not allowed hobbies"],"answer_index":2,"passage":"A gifted psychologist once remarked that worry is a kind of spasm of the mind: the mind seizes on something and simply will not let it go. Arguing with a mind in that state is futile — indeed, the stronger the will, the more futile the effort. You cannot order the worry out; you can only coax something else gently into its grip. And if that something else is well chosen, if it truly carries the illumination of a fresh field of interest, then little by little the old, excessive tension loosens, and the work of recovery begins. For anyone whose days are crowded with responsibility, the cultivation of a hobby and of new interests is therefore a policy of the first importance. But it is not a thing that can be improvised in an afternoon, or summoned up by a mere command of the will. The growth of alternative interests is slow. The seeds must be chosen with care; they must be planted in good ground; they must be tended patiently, if the living fruit is to be ready when it is wanted. To be really happy and really steady, a person ought to have two or three hobbies, and every one of them must be real. It is no use waiting until late in life to announce, ''From now on I will take an interest in this or that.'' Such an effort only aggravates the very strain it was meant to relieve. A man may gather great knowledge of subjects far from his daily work and still draw almost no comfort from it. It is no use doing what you like; you have to learn to like what you do. Broadly speaking, people may be divided into three classes: those who are worked to death, those who are worried to death, and those who are bored to death. For the laborer who has sweated through a hard week, an afternoon game of football or baseball is a real release. But it is no use asking the politician or the businessman, who has been worrying over grave matters for six days, to spend the weekend worrying over trifling ones instead. As for the fortunate few who can gratify every whim and lay their hands on almost anything they desire, a new pleasure is only one more step toward boredom. In vain they rush from place to place, hoping that sheer motion will outrun the dullness at their heels. Reasonable, useful people fall into two classes: those who keep work and play strictly apart, and those for whom the two are one. The first class is the larger, and it has its compensations — the long hours bring not only a living but a keen appetite for the simplest pleasures. Yet Fortune''s favored children belong to the second class. For them the working hours are never long enough; each day is a holiday, and holidays themselves feel like an interruption of an absorbing pursuit. And yet both classes need, at intervals, to banish the day''s work from their minds and let a change of atmosphere refresh them.","explanation_cn":"课文说:让操劳了六天大事的政客周末再为琐事操心没用,他需要真正的换脑,而非更多忧虑。✓ needs a real change."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"What does the writer say a worried mind is like?","options":["A calm lake on a still morning","A spasm in which the mind seizes on something and will not let it go","A machine that never breaks down","An empty room with nothing in it"],"answer_index":1,"audio":"A gifted psychologist once remarked that worry is a kind of spasm of the mind: the mind seizes on something and simply will not let it go. Arguing with a mind in that state is futile — indeed, the stronger the will, the more futile the effort. You cannot order the worry out; you can only coax something else gently into its grip. And if that something else is well chosen, if it truly carries the illumination of a fresh field of interest, then little by little the old, excessive tension loosens, and the work of recovery begins. For anyone whose days are crowded with responsibility, the cultivation of a hobby and of new interests is therefore a policy of the first importance. But it is not a thing that can be improvised in an afternoon, or summoned up by a mere command of the will. The growth of alternative interests is slow. The seeds must be chosen with care; they must be planted in good ground; they must be tended patiently, if the living fruit is to be ready when it is wanted. To be really happy and really steady, a person ought to have two or three hobbies, and every one of them must be real. It is no use waiting until late in life to announce, ''From now on I will take an interest in this or that.'' Such an effort only aggravates the very strain it was meant to relieve. A man may gather great knowledge of subjects far from his daily work and still draw almost no comfort from it. It is no use doing what you like; you have to learn to like what you do. Broadly speaking, people may be divided into three classes: those who are worked to death, those who are worried to death, and those who are bored to death. For the laborer who has sweated through a hard week, an afternoon game of football or baseball is a real release. But it is no use asking the politician or the businessman, who has been worrying over grave matters for six days, to spend the weekend worrying over trifling ones instead. As for the fortunate few who can gratify every whim and lay their hands on almost anything they desire, a new pleasure is only one more step toward boredom. In vain they rush from place to place, hoping that sheer motion will outrun the dullness at their heels. Reasonable, useful people fall into two classes: those who keep work and play strictly apart, and those for whom the two are one. The first class is the larger, and it has its compensations — the long hours bring not only a living but a keen appetite for the simplest pleasures. Yet Fortune''s favored children belong to the second class. For them the working hours are never long enough; each day is a holiday, and holidays themselves feel like an interruption of an absorbing pursuit. And yet both classes need, at intervals, to banish the day''s work from their minds and let a change of atmosphere refresh them.","explanation_cn":"课文说:烦恼像心灵的一阵痉挛——头脑抓住某物就不肯松手。✓ a spasm of the mind."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l46',10,NULL,'choice','{"stem":"Why do the fortunate few, who can gratify every whim, still rush from place to place?","options":["Because they are afraid of hobbies","Because they enjoy driving very much","Because for them each new pleasure only brings them one step nearer to boredom","Because they are looking for work"],"answer_index":2,"audio":"A gifted psychologist once remarked that worry is a kind of spasm of the mind: the mind seizes on something and simply will not let it go. Arguing with a mind in that state is futile — indeed, the stronger the will, the more futile the effort. You cannot order the worry out; you can only coax something else gently into its grip. And if that something else is well chosen, if it truly carries the illumination of a fresh field of interest, then little by little the old, excessive tension loosens, and the work of recovery begins. For anyone whose days are crowded with responsibility, the cultivation of a hobby and of new interests is therefore a policy of the first importance. But it is not a thing that can be improvised in an afternoon, or summoned up by a mere command of the will. The growth of alternative interests is slow. The seeds must be chosen with care; they must be planted in good ground; they must be tended patiently, if the living fruit is to be ready when it is wanted. To be really happy and really steady, a person ought to have two or three hobbies, and every one of them must be real. It is no use waiting until late in life to announce, ''From now on I will take an interest in this or that.'' Such an effort only aggravates the very strain it was meant to relieve. A man may gather great knowledge of subjects far from his daily work and still draw almost no comfort from it. It is no use doing what you like; you have to learn to like what you do. Broadly speaking, people may be divided into three classes: those who are worked to death, those who are worried to death, and those who are bored to death. For the laborer who has sweated through a hard week, an afternoon game of football or baseball is a real release. But it is no use asking the politician or the businessman, who has been worrying over grave matters for six days, to spend the weekend worrying over trifling ones instead. As for the fortunate few who can gratify every whim and lay their hands on almost anything they desire, a new pleasure is only one more step toward boredom. In vain they rush from place to place, hoping that sheer motion will outrun the dullness at their heels. Reasonable, useful people fall into two classes: those who keep work and play strictly apart, and those for whom the two are one. The first class is the larger, and it has its compensations — the long hours bring not only a living but a keen appetite for the simplest pleasures. Yet Fortune''s favored children belong to the second class. For them the working hours are never long enough; each day is a holiday, and holidays themselves feel like an interruption of an absorbing pursuit. And yet both classes need, at intervals, to banish the day''s work from their minds and let a change of atmosphere refresh them.","explanation_cn":"课文说:能满足一切心血来潮的幸运少数,每添一种新乐趣反而离厌烦更近一步,故四处奔忙。✓ nearer to boredom."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
